import assert from 'node:assert/strict';
import { issue, isValid } from '../src/token.js';
const token = issue(5, 1000);
assert.equal(isValid(token, 1000), true);
assert.equal(isValid(token, 1004), true);
assert.equal(isValid(token, 1005), false);
assert.equal(isValid(token, 2000), false);
